// FORGE built-in food database. Values are per 100 g (USDA FoodData Central / SR Legacy where available,
// otherwise typical label values for the generic product). Serving = a realistic household portion.
// Order matters: within equal search scores, earlier entries rank first, so staples come first.
// Food = { id, name, serving:{label, grams}, per100:{kcal,p,c,f,fiber}, tags:[] }  (docs/PROMPT.md §6.2)

const F = (id, name, label, grams, [kcal, p, c, f, fiber = 0], tags = []) =>
  ({ id, name, serving: { label, grams }, per100: { kcal, p, c, f, fiber }, tags });

